const BaseScraper = require('./base-scraper');
const cheerio = require('cheerio');
const axios = require('axios');

class YMCAScraper extends BaseScraper {
  constructor(config = {}) {
    super(config);

    // YMCA-specific configurations
    this.baseUrls = {
      toronto: 'https://ymcagta.org/find-a-y',
      chicago: 'https://www.ymcachicago.org/locations',
      // Add more YMCA regions as needed
    };

    this.scheduleSelectors = {
      calendar: '.schedule-calendar',
      dropIn: '.drop-in-schedule',
      programs: '.program-schedule',
      pdf: 'a[href*="schedule.pdf"]',
    };
  }

  async scrapeNearbyLocations(location, radius) {
    const results = [];

    // Determine which YMCA region to scrape based on location
    const region = this.determineRegion(location);
    if (!region || !this.baseUrls[region]) {
      this.logger.warn(`No YMCA scraper configured for location: ${JSON.stringify(location)}`);
      return results;
    }

    try {
      // First, get list of YMCA locations
      const locations = await this.scrapeLocationsList(region);

      // Filter by distance
      const nearbyLocations = locations.filter(loc => {
        if (!loc.coordinates) return false;
        const distance = this.calculateDistance(
          location.lat, location.lng,
          loc.coordinates.lat, loc.coordinates.lng
        );
        return distance <= radius;
      });

      // Scrape schedule for each nearby location
      for (const ymcaLocation of nearbyLocations) {
        try {
          const schedule = await this.scrapeLocationSchedule(ymcaLocation);
          results.push({
            source: 'ymca_scraper',
            sourceId: `ymca_${region}_${ymcaLocation.id}`,
            name: ymcaLocation.name,
            address: ymcaLocation.address,
            location: ymcaLocation.coordinates,
            type: 'community_center',
            games: schedule,
          });
        } catch (error) {
          this.logger.error(`Failed to scrape YMCA location ${ymcaLocation.name}:`, error);
        }
      }
    } catch (error) {
      this.logger.error(`YMCA scraper error for region ${region}:`, error);
    }

    return results;
  }

  determineRegion(location) {
    // Simple region determination based on coordinates
    // In production, use proper geocoding
    const regions = {
      toronto: { lat: 43.6532, lng: -79.3832, radius: 50 },
      chicago: { lat: 41.8781, lng: -87.6298, radius: 50 },
    };

    for (const [region, center] of Object.entries(regions)) {
      const distance = this.calculateDistance(
        location.lat, location.lng,
        center.lat, center.lng
      );
      if (distance <= center.radius) {
        return region;
      }
    }

    return null;
  }

  async scrapeLocationsList(region) {
    const url = this.baseUrls[region];
    const locations = [];

    try {
      const response = await axios.get(url);
      const $ = cheerio.load(response.data);

      // Parse location listings - this varies by region
      $('.location-item, .ymca-location').each((i, elem) => {
        const $elem = $(elem);

        const location = {
          id: $elem.attr('data-location-id') || i,
          name: $elem.find('.location-name, h3').text().trim(),
          address: $elem.find('.location-address, .address').text().trim(),
          url: $elem.find('a').attr('href'),
          coordinates: this.extractCoordinates($elem),
        };

        if (location.name && location.url) {
          locations.push(location);
        }
      });
    } catch (error) {
      this.logger.error(`Failed to scrape YMCA locations list for ${region}:`, error);
    }

    return locations;
  }

  async scrapeLocationSchedule(location) {
    if (!location.url) return [];

    const games = [];

    try {
      // Use Puppeteer for dynamic content
      const scheduleData = await this.scrape(location.url, () => {
        const extractSchedule = () => {
          const schedule = [];

          // Look for drop-in schedules
          const dropInElements = document.querySelectorAll('.drop-in-item, .schedule-item, .program-item');

          dropInElements.forEach(elem => {
            const text = elem.textContent;
            const timeMatch = text.match(/(\d{1,2}):(\d{2})\s*(am|pm)/gi);
            const sportMatch = text.match(/(basketball|volleyball|swimming|badminton|pickleball)/gi);

            if (timeMatch && sportMatch) {
              schedule.push({
                raw: text,
                element: elem.outerHTML,
              });
            }
          });

          // Check for PDF schedules
          const pdfLinks = Array.from(document.querySelectorAll('a[href*=".pdf"]'))
            .filter(link => link.href.toLowerCase().includes('schedule'))
            .map(link => link.href);

          return { schedule, pdfLinks };
        };

        return extractSchedule();
      });

      // Parse extracted schedule data
      for (const item of scheduleData.schedule) {
        const parsed = this.parseScheduleItem(item.raw);
        if (parsed) {
          games.push(...parsed);
        }
      }

      // Handle PDF schedules
      for (const pdfUrl of scheduleData.pdfLinks) {
        const pdfGames = await this.extractScheduleFromPDF(pdfUrl);
        if (pdfGames) {
          games.push(...pdfGames);
        }
      }

    } catch (error) {
      this.logger.error(`Failed to scrape schedule for ${location.name}:`, error);
    }

    return games;
  }

  parseScheduleItem(text) {
    const games = [];
    const today = new Date();

    // Extract day of week
    const dayMatch = text.match(/(monday|tuesday|wednesday|thursday|friday|saturday|sunday)/gi);
    if (!dayMatch) return games;

    // Extract times
    const timeMatches = text.match(/(\d{1,2}):(\d{2})\s*(am|pm)\s*-\s*(\d{1,2}):(\d{2})\s*(am|pm)/gi);
    if (!timeMatches) return games;

    // Extract sport
    const sportMatch = text.match(/(basketball|volleyball|swimming|badminton|pickleball|soccer|hockey)/gi);
    const sport = sportMatch ? sportMatch[0].toLowerCase() : 'other';

    // Extract other details
    const skillMatch = text.match(/(beginner|intermediate|advanced|all levels)/gi);
    const skillLevel = skillMatch ? skillMatch[0].toLowerCase().replace(' levels', '') : 'all';

    const priceMatch = text.match(/\$(\d+(?:\.\d{2})?)|free/gi);
    const price = priceMatch ? 
      (priceMatch[0].toLowerCase() === 'free' ? 0 : parseFloat(priceMatch[0].replace('$', ''))) : 
      0;

    // Create game entries for next 7 days
    for (const day of dayMatch) {
      const dayIndex = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday']
        .indexOf(day.toLowerCase());

      for (const timeMatch of timeMatches) {
        const [startStr, endStr] = timeMatch.split('-').map(t => t.trim());

        // Calculate next occurrence of this day
        const daysUntil = (dayIndex - today.getDay() + 7) % 7 || 7;
        const gameDate = new Date(today);
        gameDate.setDate(gameDate.getDate() + daysUntil);

        const startTime = this.parseTimeString(startStr, gameDate);
        const endTime = this.parseTimeString(endStr, gameDate);

        if (startTime && endTime) {
          games.push({
            sport,
            gameType: 'drop-in',
            startTime: startTime.toISOString(),
            endTime: endTime.toISOString(),
            skillLevel,
            price,
            metadata: {
              rawText: text,
              dayOfWeek: day,
            },
          });
        }
      }
    }

    return games;
  }

  extractCoordinates($elem) {
    // Try to extract coordinates from data attributes or nearby elements
    const lat = $elem.attr('data-lat') || $elem.find('[data-lat]').attr('data-lat');
    const lng = $elem.attr('data-lng') || $elem.find('[data-lng]').attr('data-lng');

    if (lat && lng) {
      return {
        lat: parseFloat(lat),
        lng: parseFloat(lng),
      };
    }

    // Try to extract from Google Maps link
    const mapLink = $elem.find('a[href*="maps.google.com"], a[href*="google.com/maps"]').attr('href');
    if (mapLink) {
      const coords = this.extractCoordsFromMapLink(mapLink);
      if (coords) return coords;
    }

    return null;
  }

  extractCoordsFromMapLink(url) {
    // Extract coordinates from Google Maps URL
    const patterns = [
      /@(-?\d+\.\d+),(-?\d+\.\d+)/,
      /ll=(-?\d+\.\d+),(-?\d+\.\d+)/,
      /q=(-?\d+\.\d+),(-?\d+\.\d+)/,
    ];

    for (const pattern of patterns) {
      const match = url.match(pattern);
      if (match) {
        return {
          lat: parseFloat(match[1]),
          lng: parseFloat(match[2]),
        };
      }
    }

    return null;
  }

  calculateDistance(lat1, lon1, lat2, lon2) {
    const R = 6371; // Earth's radius in km
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
              Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  }
}

module.exports = YMCAScraper;

const axios = require('axios');
const cron = require('node-cron');
const winston = require('winston');
const { RateLimiterMemory } = require('rate-limiter-flexible');

class DataAggregator {
  constructor(gameModel, cacheManager, config = {}) {
    this.gameModel = gameModel;
    this.cacheManager = cacheManager;
    this.config = config;

    this.logger = winston.createLogger({
      level: 'info',
      format: winston.format.json(),
      transports: [new winston.transports.Console()],
    });

    // Initialize data sources
    this.dataSources = new Map();
    this.initializeDataSources();

    // Rate limiters for each API
    this.rateLimiters = new Map();
    this.initializeRateLimiters();

    // Track sync status
    this.syncStatus = new Map();
  }

  initializeDataSources() {
    // Google Places API
    if (this.config.googlePlacesApiKey) {
      this.dataSources.set('google_places', {
        name: 'Google Places API',
        enabled: true,
        priority: 1,
        handler: this.fetchGooglePlacesData.bind(this),
        rateLimit: { points: 100, duration: 60 }, // 100 requests per minute
      });
    }

    // Municipal APIs
    this.dataSources.set('toronto_open_data', {
      name: 'Toronto Open Data',
      enabled: true,
      priority: 2,
      handler: this.fetchTorontoData.bind(this),
      rateLimit: { points: 60, duration: 60 },
    });

    this.dataSources.set('nyc_open_data', {
      name: 'NYC Open Data',
      enabled: true,
      priority: 2,
      handler: this.fetchNYCData.bind(this),
      rateLimit: { points: 60, duration: 60 },
    });

    // Recreation Management Systems
    this.dataSources.set('activenet', {
      name: 'ActiveNet',
      enabled: false, // Requires API key
      priority: 3,
      handler: this.fetchActiveNetData.bind(this),
      rateLimit: { points: 30, duration: 60 },
    });

    // Web Scrapers
    this.dataSources.set('ymca_scraper', {
      name: 'YMCA Scraper',
      enabled: true,
      priority: 4,
      handler: this.scrapeYMCAData.bind(this),
      rateLimit: { points: 10, duration: 60 },
    });

    this.dataSources.set('community_center_scraper', {
      name: 'Community Center Scraper',
      enabled: true,
      priority: 4,
      handler: this.scrapeCommunityData.bind(this),
      rateLimit: { points: 20, duration: 60 },
    });

    // RSS/Email parsers
    this.dataSources.set('rss_parser', {
      name: 'RSS Feed Parser',
      enabled: true,
      priority: 5,
      handler: this.parseRSSFeeds.bind(this),
      rateLimit: { points: 30, duration: 60 },
    });
  }

  initializeRateLimiters() {
    for (const [key, source] of this.dataSources) {
      if (source.rateLimit) {
        this.rateLimiters.set(key, new RateLimiterMemory({
          points: source.rateLimit.points,
          duration: source.rateLimit.duration,
        }));
      }
    }
  }

  async aggregateData(location, radius = 10) {
    const results = {
      success: [],
      failed: [],
      totalVenues: 0,
      totalGames: 0,
    };

    // Sort sources by priority
    const sortedSources = Array.from(this.dataSources.entries())
      .filter(([_, source]) => source.enabled)
      .sort((a, b) => a[1].priority - b[1].priority);

    // Fetch data from each source in parallel with rate limiting
    const promises = sortedSources.map(async ([key, source]) => {
      try {
        // Check rate limit
        const rateLimiter = this.rateLimiters.get(key);
        if (rateLimiter) {
          await rateLimiter.consume(key);
        }

        const startTime = Date.now();
        const data = await source.handler(location, radius);
        const duration = Date.now() - startTime;

        // Process and store data
        const processed = await this.processSourceData(key, data);

        results.success.push({
          source: source.name,
          venuesFound: processed.venues,
          gamesFound: processed.games,
          duration,
        });

        results.totalVenues += processed.venues;
        results.totalGames += processed.games;

        this.logger.info(`${source.name}: Found ${processed.venues} venues, ${processed.games} games in ${duration}ms`);
      } catch (error) {
        results.failed.push({
          source: source.name,
          error: error.message,
        });
        this.logger.error(`${source.name} failed:`, error);
      }
    });

    await Promise.allSettled(promises);

    // Invalidate cache for the area
    await this.cacheManager.invalidate(`search:${location.geohash}`);

    return results;
  }

  async fetchGooglePlacesData(location, radius) {
    const types = ['gym', 'stadium', 'park'];
    const results = [];

    for (const type of types) {
      const response = await axios.get('https://maps.googleapis.com/maps/api/place/nearbysearch/json', {
        params: {
          location: `${location.lat},${location.lng}`,
          radius: radius * 1000,
          type,
          key: this.config.googlePlacesApiKey,
        },
      });

      if (response.data.results) {
        results.push(...response.data.results.map(place => ({
          source: 'google_places',
          sourceId: place.place_id,
          name: place.name,
          address: place.vicinity,
          location: place.geometry.location,
          types: place.types,
          rating: place.rating,
          openingHours: place.opening_hours,
        })));
      }
    }

    return results;
  }

  async fetchTorontoData(location, radius) {
    try {
      // Toronto Recreation Facilities
      const response = await axios.get('https://ckan0.cf.opendata.inter.prod-toronto.ca/api/3/action/datastore_search', {
        params: {
          resource_id: 'e7c6e6cc-2e4f-4abd-8da3-87f595926744', // Recreation facilities dataset
          limit: 500,
        },
      });

      const facilities = response.data.result.records || [];

      // Filter by distance (simple approximation)
      const nearbyFacilities = facilities.filter(facility => {
        if (!facility.Latitude || !facility.Longitude) return false;
        const distance = this.calculateDistance(
          location.lat, location.lng,
          parseFloat(facility.Latitude), parseFloat(facility.Longitude)
        );
        return distance <= radius;
      });

      return nearbyFacilities.map(facility => ({
        source: 'toronto_open_data',
        sourceId: facility._id,
        name: facility.Name,
        address: facility.Address,
        location: {
          lat: parseFloat(facility.Latitude),
          lng: parseFloat(facility.Longitude),
        },
        type: facility.FacilityType,
        programs: facility.Programs,
      }));
    } catch (error) {
      this.logger.error('Toronto API error:', error);
      return [];
    }
  }

  async fetchNYCData(location, radius) {
    try {
      const response = await axios.get('https://data.cityofnewyork.us/resource/xx67-kt59.json', {
        params: {
          $limit: 500,
          $where: `latitude IS NOT NULL AND longitude IS NOT NULL`,
        },
      });

      const facilities = response.data || [];

      // Filter by distance
      const nearbyFacilities = facilities.filter(facility => {
        const distance = this.calculateDistance(
          location.lat, location.lng,
          parseFloat(facility.latitude), parseFloat(facility.longitude)
        );
        return distance <= radius;
      });

      return nearbyFacilities.map(facility => ({
        source: 'nyc_open_data',
        sourceId: facility.prop_id,
        name: facility.name,
        address: facility.location,
        location: {
          lat: parseFloat(facility.latitude),
          lng: parseFloat(facility.longitude),
        },
        type: 'athletic_facility',
        sports: facility.sports,
      }));
    } catch (error) {
      this.logger.error('NYC API error:', error);
      return [];
    }
  }

  async fetchActiveNetData(location, radius) {
    // ActiveNet requires authentication and custom implementation
    // This is a placeholder for when API credentials are available
    return [];
  }

  async scrapeYMCAData(location, radius) {
    // Implementation would use puppeteer to scrape YMCA websites
    // This is a simplified version
    const YMCAScraper = require('../scrapers/ymca-scraper');
    const scraper = new YMCAScraper();

    try {
      return await scraper.scrapeNearbyLocations(location, radius);
    } catch (error) {
      this.logger.error('YMCA scraper error:', error);
      return [];
    }
  }

  async scrapeCommunityData(location, radius) {
    // Implementation would scrape various community center websites
    const CommunityScraper = require('../scrapers/community-scraper');
    const scraper = new CommunityScraper();

    try {
      return await scraper.scrapeNearbyLocations(location, radius);
    } catch (error) {
      this.logger.error('Community scraper error:', error);
      return [];
    }
  }

  async parseRSSFeeds(location, radius) {
    const RSSParser = require('rss-parser');
    const parser = new RSSParser();

    // List of RSS feeds for sports venues (would be configured)
    const feeds = this.config.rssFeeds || [];
    const results = [];

    for (const feedUrl of feeds) {
      try {
        const feed = await parser.parseURL(feedUrl);
        // Parse and filter feed items for sports events
        // This is a simplified implementation
        results.push(...this.parseRSSItems(feed.items, location, radius));
      } catch (error) {
        this.logger.error(`RSS feed error (${feedUrl}):`, error);
      }
    }

    return results;
  }

  async processSourceData(source, data) {
    let venueCount = 0;
    let gameCount = 0;

    for (const item of data) {
      try {
        // Add or update venue
        const venue = await this.gameModel.addVenue({
          name: item.name,
          address: item.address,
          latitude: item.location.lat,
          longitude: item.location.lng || item.location.lon,
          type: this.mapVenueType(item.type || item.types),
          source: item.source,
          sourceId: item.sourceId,
          metadata: item,
        });
        venueCount++;

        // Extract games if available
        if (item.games || item.schedule) {
          const games = Array.isArray(item.games) ? item.games : [item.games].filter(Boolean);

          for (const game of games) {
            await this.gameModel.addGame({
              venueId: venue.id,
              sport: this.mapSportType(game.sport || game.activity),
              gameType: game.type || 'drop-in',
              startTime: new Date(game.startTime),
              endTime: new Date(game.endTime),
              capacity: game.capacity,
              skillLevel: game.skillLevel || 'all',
              price: game.price || 0,
              source: item.source,
              metadata: game,
            });
            gameCount++;
          }
        }
      } catch (error) {
        this.logger.error(`Error processing ${source} data:`, error);
      }
    }

    return { venues: venueCount, games: gameCount };
  }

  mapVenueType(types) {
    if (!types) return 'other';

    const typeArray = Array.isArray(types) ? types : [types];
    const typeString = typeArray.join(' ').toLowerCase();

    if (typeString.includes('gym') || typeString.includes('fitness')) return 'gym';
    if (typeString.includes('park')) return 'park';
    if (typeString.includes('arena') || typeString.includes('rink')) return 'arena';
    if (typeString.includes('community') || typeString.includes('recreation')) return 'community_center';

    return 'other';
  }

  mapSportType(activity) {
    if (!activity) return 'other';

    const normalized = activity.toLowerCase();
    const sportMap = {
      'basketball': ['basketball', 'hoops', 'bball'],
      'soccer': ['soccer', 'football', 'futbol'],
      'hockey': ['hockey', 'ice hockey', 'floor hockey'],
      'volleyball': ['volleyball', 'vball'],
      'tennis': ['tennis'],
      'pickleball': ['pickleball'],
      'badminton': ['badminton'],
      'baseball': ['baseball', 'softball'],
      'football': ['football', 'american football'],
    };

    for (const [sport, keywords] of Object.entries(sportMap)) {
      if (keywords.some(keyword => normalized.includes(keyword))) {
        return sport;
      }
    }

    return 'other';
  }

  calculateDistance(lat1, lon1, lat2, lon2) {
    const R = 6371; // Earth's radius in km
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
              Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  }

  async startScheduledSync() {
    // Sync data every hour for major cities
    cron.schedule('0 * * * *', async () => {
      this.logger.info('Starting scheduled data sync...');

      const majorCities = this.config.majorCities || [
        { name: 'Toronto', lat: 43.6532, lng: -79.3832 },
        { name: 'New York', lat: 40.7128, lng: -74.0060 },
        { name: 'Chicago', lat: 41.8781, lng: -87.6298 },
      ];

      for (const city of majorCities) {
        try {
          const result = await this.aggregateData({
            lat: city.lat,
            lng: city.lng,
            geohash: geohash.encode(city.lat, city.lng, 4),
          }, 20); // 20km radius for major cities

          this.syncStatus.set(city.name, {
            lastSync: new Date(),
            result,
          });
        } catch (error) {
          this.logger.error(`Sync failed for ${city.name}:`, error);
        }
      }
    });
  }

  getSyncStatus() {
    return Object.fromEntries(this.syncStatus);
  }
}

